    ('22222222-0000-0000-0000-000000000001'::uuid, '買い物に行く', 'Dùng để nói đi mua sắm nói chung; trợ từ に đứng trước 行く để chỉ mục đích.', ARRAY['週末に買い物に行く', '母と買い物をする']::text[], ARRAY['Cuối tuần đi mua sắm', 'Đi mua sắm cùng mẹ']::text[], ARRAY['Chỉ hoạt động mua sắm nói chung, không nhấn một món cụ thể.', 'Có thể dùng 買い物をする hoặc 買い物に行く.']::text[], ARRAY['ショッピング', '買い出し']::text[], ARRAY['mua sắm', 'đi mua đồ cần dùng']::text[], ARRAY['買い出し']::text[], ARRAY['Mua sắm nói chung, dùng được trong hội thoại hằng ngày.']::text[], ARRAY['Thường mua đồ cần thiết cho một mục đích cụ thể.']::text[], 'Không nói 買い物を行きます. Khi đi mua sắm, dùng 買い物に行きます.', ARRAY['買い物に行く', '買い物をする']::text[]),
    ('22222222-0000-0000-0000-000000000002'::uuid, 'Nを買う', 'Động từ mua một món hàng cụ thể; tân ngữ đi với を.', ARRAY['新しい靴を買う', 'スーパーで牛乳を買う']::text[], ARRAY['Mua đôi giày mới', 'Mua sữa ở siêu thị']::text[], ARRAY['Nhấn vào hành động mua một món cụ thể.', 'Dạng lịch sự là 買います.']::text[], ARRAY['買い物をする']::text[], ARRAY['đi mua sắm']::text[], ARRAY['買い物をする']::text[], ARRAY['Mua đồ nói chung, không cần nêu món cụ thể.']::text[], ARRAY['Tập trung vào việc mua một món cụ thể.']::text[], 'Không dùng に sau món đồ. Món được mua đi với を.', ARRAY['Nを買う']::text[]),
    ('22222222-0000-0000-0000-000000000003'::uuid, 'Nは高い', 'Tính từ -i: giá cao hoặc chiều cao lớn tùy danh từ đi trước.', ARRAY['このかばんは高い', '富士山は高い']::text[], ARRAY['Cái túi này đắt', 'Núi Phú Sĩ cao']::text[], ARRAY['Với đồ vật, 高い thường là đắt.', 'Với người, núi, tòa nhà, 高い là cao.']::text[], ARRAY['安い']::text[], ARRAY['rẻ']::text[], ARRAY['安い']::text[], ARRAY['Đắt hoặc cao tùy ngữ cảnh.']::text[], ARRAY['Rẻ, là nghĩa đối lập khi nói về giá.']::text[], 'Đừng luôn dịch 高い là cao; khi nói về giá phải hiểu là đắt.', ARRAY['đắt', 'cao']::text[]),
    ('22222222-0000-0000-0000-000000000004'::uuid, 'Nは安い', 'Tính từ -i chỉ giá thấp, rẻ; thường dùng khi mua sắm.', ARRAY['この店は安い', '安い野菜を買う']::text[], ARRAY['Cửa hàng này rẻ', 'Mua rau rẻ']::text[], ARRAY['Chỉ nói về giá thấp, không có nghĩa là chất lượng kém.', 'Có thể bổ nghĩa danh từ: 安い店.']::text[], ARRAY['高い']::text[], ARRAY['đắt, cao']::text[], ARRAY['高い']::text[], ARRAY['Rẻ, giá thấp.']::text[], ARRAY['Đắt hoặc cao.']::text[], 'Không dùng 安い để nói người thấp; người thấp là 背が低い.', ARRAY['rẻ', 'giá thấp']::text[]),
    ('22222222-0000-0000-0000-000000000006'::uuid, 'お金がかかる／お金を払う', 'お金 là tiền nói chung; đi với かかる khi nói chi phí và 払う khi nói trả tiền.', ARRAY['旅行はお金がかかる', 'レジでお金を払う']::text[], ARRAY['Du lịch tốn tiền', 'Trả tiền ở quầy thu ngân']::text[], ARRAY['Có お là cách nói lịch sự, tự nhiên hằng ngày.', 'Không đếm お金 bằng số lượng món đồ.']::text[], ARRAY['値段', '料金']::text[], ARRAY['giá của món hàng', 'phí dịch vụ']::text[], ARRAY['値段']::text[], ARRAY['Tiền dùng để trả hoặc số tiền có trong tay.']::text[], ARRAY['Mức giá gắn với một món cụ thể.']::text[], 'お金 không có nghĩa là giá. Hỏi giá một món dùng 値段はいくらですか.', ARRAY['お金を払う', '値段を聞く']::text[]),
    ('22222222-0000-0000-0000-000000000007'::uuid, 'Nの値段はいくらですか', '値段 là giá của một món hàng; thường đi với いくら để hỏi giá.', ARRAY['この時計の値段はいくらですか', '値段を見てから買う']::text[], ARRAY['Đồng hồ này giá bao nhiêu?', 'Xem giá rồi mới mua']::text[], ARRAY['Dùng chủ yếu cho hàng hóa cụ thể.', 'Lịch sự hơn có thể nói お値段.']::text[], ARRAY['料金', 'お金']::text[], ARRAY['phí dịch vụ', 'tiền']::text[], ARRAY['料金']::text[], ARRAY['Giá của món đồ để mua.']::text[], ARRAY['Phí trả cho tàu xe, dịch vụ hoặc sử dụng.']::text[], 'Không nói 値段を払います. Trả tiền dùng お金を払います.', ARRAY['Nの値段', 'いくらですか']::text[]),
    ('22222222-0000-0000-0000-000000000008'::uuid, 'デパートでNを買う', 'デパート là trung tâm bách hóa; dùng で để nói nơi diễn ra việc mua sắm.', ARRAY['デパートで服を買う', 'デパートは駅の近くにある']::text[], ARRAY['Mua quần áo ở trung tâm thương mại', 'Trung tâm bách hóa ở gần ga']::text[], ARRAY['Thường gợi nơi bán hàng quy mô lớn, nhiều tầng.', 'Dùng で khi mua ở đó; dùng に khi đi đến đó.']::text[], ARRAY['スーパー']::text[], ARRAY['siêu thị']::text[], ARRAY['スーパー']::text[], ARRAY['Nhiều quầy, thường có quần áo và hàng hóa đa dạng.']::text[], ARRAY['Thiên về thực phẩm và đồ dùng hằng ngày.']::text[], 'Phân biệt nơi chốn: デパートへ行く nhưng デパートで買う.', ARRAY['へ行く', 'で買う']::text[]),
    ('22222222-0000-0000-0000-000000000009'::uuid, 'スーパーでNを買う', 'スーパー là siêu thị, nơi thường mua thực phẩm và đồ dùng hằng ngày.', ARRAY['スーパーで野菜を買う', '家の近くにスーパーがある']::text[], ARRAY['Mua rau ở siêu thị', 'Gần nhà có siêu thị']::text[], ARRAY['Từ mượn, thường dùng trong hội thoại hằng ngày.', 'Không nhất thiết lớn như デパート.']::text[], ARRAY['デパート']::text[], ARRAY['trung tâm bách hóa']::text[], ARRAY['デパート']::text[], ARRAY['Thiên về thực phẩm và nhu yếu phẩm.']::text[], ARRAY['Nhiều loại hàng hóa hơn, thường lớn và trang trọng hơn.']::text[], 'Đừng dùng に để nói nơi mua: スーパーで買います.', ARRAY['スーパーで買う']::text[]),
    ('22222222-0000-0000-0000-000000000010'::uuid, '財布を持つ／忘れる', '財布 là ví để đựng tiền, thẻ; thường đi với 持つ hoặc 忘れる.', ARRAY['財布を持って行く', '財布を家に忘れた']::text[], ARRAY['Mang ví đi', 'Quên ví ở nhà']::text[], ARRAY['Là vật đựng tiền, không đồng nghĩa với tiền.', 'Trong hội thoại thường dùng với お金.']::text[], ARRAY['お金']::text[], ARRAY['tiền']::text[], ARRAY['お金']::text[], ARRAY['Đồ dùng để cất tiền và thẻ.']::text[], ARRAY['Bản thân tiền để trả hoặc sở hữu.']::text[], 'Không nói 財布を払います. Trả tiền là お金を払います.', ARRAY['財布を持つ', 'お金を払う']::text[]),
    ('22222222-0000-0000-0000-000000000011'::uuid, 'レジで払う', 'レジ là quầy hoặc máy tính tiền; dùng で khi thanh toán ở đó.', ARRAY['レジでお金を払う', 'レジに並ぶ']::text[], ARRAY['Trả tiền ở quầy thu ngân', 'Xếp hàng ở quầy thu ngân']::text[], ARRAY['Từ mượn từ register, dùng rất phổ biến.', 'Có thể nói レジの前 để chỉ phía trước quầy.']::text[], ARRAY['会計']::text[], ARRAY['thanh toán, hóa đơn']::text[], ARRAY['会計']::text[], ARRAY['Nơi/thiết bị tính tiền trong cửa hàng.']::text[], ARRAY['Hành động hoặc khoản thanh toán.']::text[], 'Không dùng レジを払います. Dùng レジで払います.', ARRAY['レジで払う', 'レジに並ぶ']::text[]),
    ('22222222-0000-0000-0000-000000000013'::uuid, '学校へ行く／学校で学ぶ', '学校 là trường học; へ chỉ hướng đi, で chỉ nơi diễn ra hành động.', ARRAY['毎日学校へ行く', '学校で日本語を学ぶ']::text[], ARRAY['Hằng ngày đi đến trường', 'Học tiếng Nhật ở trường']::text[], ARRAY['Có thể là trường nói chung, không chỉ lớp học cụ thể.', 'Phân biệt với 教室 là phòng học bên trong trường.']::text[], ARRAY['教室']::text[], ARRAY['phòng học']::text[], ARRAY['教室']::text[], ARRAY['Cả cơ sở/trường học.']::text[], ARRAY['Một phòng cụ thể để học.']::text[], 'Không nói 学校に勉強します. Nơi học đi với で: 学校で勉強します.', ARRAY['学校へ行く', '学校で勉強する']::text[]),
    ('22222222-0000-0000-0000-000000000014'::uuid, '先生に聞く／教わる', '先生 là giáo viên hoặc cách gọi lịch sự một số chuyên gia; dùng に với người nhận câu hỏi.', ARRAY['先生に質問する', '先生に日本語を教わる']::text[], ARRAY['Hỏi giáo viên', 'Học tiếng Nhật từ giáo viên']::text[], ARRAY['Dùng để gọi trực tiếp hoặc nói về giáo viên người khác.', 'Không dùng 先生 để nói về nghề nghiệp của chính mình.']::text[], ARRAY['教師']::text[], ARRAY['giáo viên, cách nói nghề nghiệp']::text[], ARRAY['教師']::text[], ARRAY['Cách gọi tôn trọng người đang dạy.']::text[], ARRAY['Tên nghề giáo viên, trung tính hơn.']::text[], 'Khi nói nghề của mình, dùng 教師; không tự gọi mình là 先生.', ARRAY['先生に聞く', '教師です']::text[]),
    ('22222222-0000-0000-0000-000000000015'::uuid, '学生です／学生生活', '学生 là học sinh, sinh viên nói chung; thường làm vị ngữ với です.', ARRAY['私は大学の学生です', '学生は図書館で勉強する']::text[], ARRAY['Tôi là sinh viên đại học', 'Học sinh, sinh viên học ở thư viện']::text[], ARRAY['Bao quát người đang đi học, tùy ngữ cảnh có thể là học sinh hoặc sinh viên.', 'Dùng 学生の trước danh từ.']::text[], ARRAY['生徒']::text[], ARRAY['học sinh tại trường phổ thông']::text[], ARRAY['生徒']::text[], ARRAY['Người đang đi học nói chung, đặc biệt dùng cho sinh viên.']::text[], ARRAY['Thường chỉ học sinh ở một trường/lớp cụ thể.']::text[], 'Không dùng 学生 để gọi người nghe như một danh xưng lịch sự; dùng tên hoặc さん.', ARRAY['学生です', '学生の本']::text[]),
    ('22222222-0000-0000-0000-000000000016'::uuid, '教室で勉強する', '教室 là phòng học; dùng で để chỉ nơi hành động học diễn ra.', ARRAY['教室で勉強する', '教室に先生がいる']::text[], ARRAY['Học trong lớp', 'Có giáo viên trong lớp']::text[], ARRAY['Chỉ không gian phòng cụ thể bên trong trường.', 'Với sự tồn tại người/vật dùng に và いる／ある.']::text[], ARRAY['学校']::text[], ARRAY['trường học']::text[], ARRAY['学校']::text[], ARRAY['Một phòng học cụ thể.']::text[], ARRAY['Cả trường/cơ sở giáo dục.']::text[], 'Phân biệt trợ từ: 教室で勉強する nhưng 教室に先生がいます.', ARRAY['で勉強する', 'にいます']::text[]),
    ('22222222-0000-0000-0000-000000000017'::uuid, 'Nを勉強する', '勉強する là học một môn/chủ đề; đối tượng học đi với を.', ARRAY['日本語を勉強する', '毎日一時間勉強する']::text[], ARRAY['Học tiếng Nhật', 'Mỗi ngày học một tiếng']::text[], ARRAY['Dùng rất tự nhiên cho việc học có chủ đích.', 'Có thể dùng 勉強します không cần nêu môn học.']::text[], ARRAY['学ぶ']::text[], ARRAY['học, tiếp thu']::text[], ARRAY['学ぶ']::text[], ARRAY['Nhấn việc học tập/luyện tập cụ thể.']::text[], ARRAY['Rộng hơn, có sắc thái học hỏi hoặc tiếp thu kiến thức.']::text[], 'Không dùng に với môn học: 日本語を勉強します.', ARRAY['Nを勉強する', '一時間勉強する']::text[]),
    ('22222222-0000-0000-0000-000000000018'::uuid, '授業が始まる／ある', '授業 là tiết học hoặc bài giảng; thường đi với 始まる, 終わる, ある.', ARRAY['授業は九時に始まる', '今日は日本語の授業がある']::text[], ARRAY['Tiết học bắt đầu lúc 9 giờ', 'Hôm nay có tiết tiếng Nhật']::text[], ARRAY['Chỉ một buổi/tiết học theo lịch.', 'Khác với 勉強 là hoạt động học của cá nhân.']::text[], ARRAY['勉強']::text[], ARRAY['việc học tập']::text[], ARRAY['勉強']::text[], ARRAY['Tiết/bài học có lịch hoặc do giáo viên dạy.']::text[], ARRAY['Việc học của người học nói chung.']::text[], 'Không nói 授業を勉強します. Học môn nào dùng Nを勉強します.', ARRAY['授業がある', '授業が始まる']::text[]),
    ('22222222-0000-0000-0000-000000000023'::uuid, '休みです／休みを取る', '休み là ngày nghỉ, kỳ nghỉ hoặc sự nghỉ ngơi tùy ngữ cảnh.', ARRAY['今日は休みです', '明日休みを取る']::text[], ARRAY['Hôm nay là ngày nghỉ', 'Ngày mai xin nghỉ']::text[], ARRAY['Có thể là danh từ; động từ nghỉ là 休みます.', 'Nghĩa ngày nghỉ thường dùng với です.']::text[], ARRAY['休憩']::text[], ARRAY['giải lao ngắn']::text[], ARRAY['休憩']::text[], ARRAY['Ngày nghỉ hoặc sự nghỉ nói chung.']::text[], ARRAY['Nghỉ giải lao ngắn trong lúc làm/học.']::text[], 'Đừng nhầm 休みです (ngày nghỉ) với 休みます (tôi nghỉ).', ARRAY['休みです', '休みます']::text[]),
    ('22222222-0000-0000-0000-000000000025'::uuid, '今日＋câu', '今日 là hôm nay; thường không cần trợ từ に trước hành động.', ARRAY['今日、学校へ行く', '今日は暑い']::text[], ARRAY['Hôm nay đi đến trường', 'Hôm nay trời nóng']::text[], ARRAY['Có thể thêm は để nêu chủ đề: 今日は.', 'Dùng dấu ngắt tự nhiên sau 今日 trong câu nói.']::text[], ARRAY['明日', '昨日']::text[], ARRAY['ngày mai', 'hôm qua']::text[], ARRAY['明日']::text[], ARRAY['Ngày đang diễn ra.']::text[], ARRAY['Ngày kế tiếp.']::text[], 'Không thêm に sau 今日 trong cách nói cơ bản: 今日学校へ行きます.', ARRAY['今日は', '今日、']::text[]),
    ('22222222-0000-0000-0000-000000000026'::uuid, '明日＋câu', '明日 là ngày mai; thường đứng đầu câu, không cần に trong mẫu cơ bản.', ARRAY['明日また来る', '明日は休みです']::text[], ARRAY['Ngày mai lại đến', 'Ngày mai là ngày nghỉ']::text[], ARRAY['Có thể nói あした hoặc あす tùy ngữ cảnh.', 'あした là cách đọc thân mật, phổ biến ở N5.']::text[], ARRAY['今日', '昨日']::text[], ARRAY['hôm nay', 'hôm qua']::text[], ARRAY['今日']::text[], ARRAY['Ngày kế tiếp so với hôm nay.']::text[], ARRAY['Ngày đang diễn ra.']::text[], 'Không dùng 明日に trong cách nói thời gian N5 thông thường.', ARRAY['明日は', '明日、']::text[]),
    ('22222222-0000-0000-0000-000000000028'::uuid, 'N時間／時間がかかる', '時間 là thời gian hoặc đơn vị giờ; N時間 diễn tả khoảng thời lượng.', ARRAY['二時間勉強する', '駅まで一時間かかる']::text[], ARRAY['Học hai tiếng', 'Đến ga mất một tiếng']::text[], ARRAY['時間 là khoảng thời gian, khác 時 là một thời điểm.', 'Đi với かかる để nói mất bao lâu.']::text[], ARRAY['時']::text[], ARRAY['giờ, thời điểm']::text[], ARRAY['時']::text[], ARRAY['Khoảng thời lượng như hai tiếng.']::text[], ARRAY['Mốc giờ cụ thể như ba giờ.']::text[], 'Không dùng 三時間に. Thời lượng N時間 thường không cần に.', ARRAY['二時間', '時間がかかる']::text[]),
    ('22222222-0000-0000-0000-000000000029'::uuid, '電話をかける／電話する', '電話 là điện thoại hoặc cuộc gọi; 電話をかける và 電話する đều là gọi điện.', ARRAY['友達に電話をかける', '母に電話する']::text[], ARRAY['Gọi điện cho bạn', 'Gọi điện cho mẹ']::text[], ARRAY['Đối tượng nhận cuộc gọi đi với に.', '電話する là cách nói gọn, rất phổ biến.']::text[], ARRAY['スマホ']::text[], ARRAY['điện thoại thông minh']::text[], ARRAY['電話する']::text[], ARRAY['Hành động gọi điện hoặc điện thoại nói chung.']::text[], ARRAY['Cách nói ngắn cho hành động gọi điện.']::text[], 'Người nhận cuộc gọi đi với に, không đi với を.', ARRAY['Nに電話する', '電話をかける']::text[]),
    ('22222222-0000-0000-0000-000000000030'::uuid, '家族と／家族は', '家族 là gia đình nói chung; dùng と khi làm cùng gia đình, は khi nêu gia đình làm chủ đề.', ARRAY['家族と旅行する', '家族は四人です']::text[], ARRAY['Đi du lịch cùng gia đình', 'Gia đình có bốn người']::text[], ARRAY['Bao gồm mọi thành viên trong nhà.', 'Khi hỏi lịch sự về nhà người khác thường dùng ご家族.']::text[], ARRAY['両親']::text[], ARRAY['cha mẹ']::text[], ARRAY['両親']::text[], ARRAY['Toàn bộ thành viên gia đình.']::text[], ARRAY['Chỉ cha và mẹ.']::text[], 'Không dùng ご家族 để nói về gia đình mình trong ngữ cảnh lịch sự; dùng 家族.', ARRAY['家族と', 'ご家族']::text[])
)
update vocabulary as v
set
  common_usage_pattern = content.pattern,
  common_usage_desc = content.usage_desc,
  common_usage_examples_jp = content.usage_jp,
  common_usage_examples_vi = content.usage_vi,
  nuance_points = content.nuance,
  similar_words = content.similar_words_data,
  similar_words_meaning_vi = content.similar_vi,
  comparison_words = content.comparison_words,
  comparison_main_descs = content.comparison_main,
  comparison_other_descs = content.comparison_other,
  common_mistake_note = content.mistake,
  common_mistake_suggestions = content.suggestions
from content
where v.id = content.id
  and v.level_id = (select id from jlpt_levels where code = 'N5');
